// Herodian Accent Toy (offline, heuristic)

const $ = (id) => document.getElementById(id);

// --- Unicode helpers for Greek accents ---
// We treat accents as combining marks (U+0301 acute, U+0342 circumflex, U+0300 grave)
// and also precomposed Greek letters with tonos/oxia/varia/perispomeni.

const COMBINING_ACCENTS = new Set(["\u0301","\u0342","\u0300"]);

function stripCombiningAccents(s){
  return s.normalize('NFD').split('').filter(ch => !COMBINING_ACCENTS.has(ch)).join('').normalize('NFC');
}

function hasAnyAccent(s){
  const nfd = s.normalize('NFD');
  for (const ch of nfd){
    if (COMBINING_ACCENTS.has(ch)) return true;
  }
  // also catch precomposed tonos/oxia/varia/perispomeni by comparing stripped
  return stripCombiningAccents(s) !== s;
}

function lastVowelIndexNFD(nfd){
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  // In NFD, precomposed vowels become base vowel + combining marks.
  // We'll scan for base vowel letters.
  for (let i = nfd.length - 1; i >= 0; i--){
    if (vowels.has(nfd[i])) return i;
  }
  return -1;
}

function prevVowelIndexNFD(nfd, fromIndex){
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  for (let i = fromIndex - 1; i >= 0; i--){
    if (vowels.has(nfd[i])) return i;
  }
  return -1;
}

function accentOnLastSyllableHeuristic(s){
  // Heuristic: if any accent mark occurs after the last vowel base letter, or on it.
  // More robust: locate last vowel base index; check if an accent combining mark follows it
  // before the next base letter (which won't exist).
  const nfd = s.normalize('NFD');
  const lv = lastVowelIndexNFD(nfd);
  if (lv < 0) return false;
  for (let i = lv + 1; i < nfd.length; i++){
    if (COMBINING_ACCENTS.has(nfd[i])) return true;
  }
  // also if the vowel itself is precomposed with accent, NFD would have combining mark after it.
  return false;
}

function moveAccentLeftOneVowel(s){
  // If there is an accent on the last vowel, remove it and add acute to previous vowel.
  // If no accent, return original.
  const nfd = s.normalize('NFD');
  const lv = lastVowelIndexNFD(nfd);
  if (lv < 0) return s;

  // Determine if last vowel has an accent combining mark after it
  let hasLastAccent = false;
  let end = nfd.length;
  for (let i = lv + 1; i < nfd.length; i++){
    if (COMBINING_ACCENTS.has(nfd[i])) hasLastAccent = true;
  }
  if (!hasLastAccent) return s;

  const pv = prevVowelIndexNFD(nfd, lv);
  if (pv < 0) return stripCombiningAccents(s); // nowhere to move; just de-accent

  // Remove all combining accents after last vowel
  let arr = nfd.split('');
  for (let i = arr.length - 1; i > lv; i--){
    if (COMBINING_ACCENTS.has(arr[i])) arr.splice(i,1);
  }

  // Also remove any accents already on previous vowel (to avoid double marks)
  for (let i = pv + 1; i < arr.length; i++){
    if (COMBINING_ACCENTS.has(arr[i])){
      // stop removing once we hit another base letter (rough)
      // but since we don't track base letters well, just remove immediate combining marks
      // until a non-combining appears.
      // We'll remove consecutive combining marks right after pv.
      break;
    }
  }
  // Remove consecutive combining marks after pv
  while (arr[pv+1] && COMBINING_ACCENTS.has(arr[pv+1])) arr.splice(pv+1,1);

  // Add acute (oxia) to previous vowel
  arr.splice(pv+1, 0, "\u0301");

  return arr.join('').normalize('NFC');
}

// --- Herodian-ish ending classifier ---

const ENDING_RULES = [
  { ending: 'ινης', label: "-ινης", tendency: 'barytone', note: "Proper names in -ινης are said to be barytone (e.g. Αἰσχίνης)." },
  { ending: 'ονης', label: "-ονης", tendency: 'barytone', note: "-ονης barytone (e.g. Μηριόνης)." },
  { ending: 'υνης', label: "-υνης", tendency: 'barytone', note: "-υνης barytone (e.g. Κερύνης)." },
  { ending: 'ωνης', label: "-ωνης", tendency: 'barytone', note: "-ωνης barytone (e.g. τελώνης)." },
  { ending: 'ξης', label: "-ξης", tendency: 'barytone', note: "-ξης barytone (e.g. Ἀράξης)." },
  { ending: 'πης', label: "-πης", tendency: 'barytone', note: "-πης barytone (e.g. Παντικάπης, Ὑστάσπης)." },
  { ending: 'αρης', label: "-αρης", tendency: 'barytone', note: "-αρης barytone unless it’s an adjective (exception mentioned: θυμαρής is oxytone)." },
  { ending: 'ερης', label: "-ερης", tendency: 'barytone?', note: "-ερης barytone if genitive is -ητος (e.g. Ὑπέρης ~ Ὑπέρητος). But ἀμερής (gen. -ους) is oxytone." },
  { ending: 'ηρης', label: "-ηρης", tendency: 'barytone', note: "-ηρης barytone (e.g. χαλκήρης, χρυσήρης, θυμήρης)." },
  { ending: 'ης', label: "-ης", tendency: 'mixed', note: "Many -ης words vary; this passage highlights some special cases (e.g. θυμαρής oxytone)." }
];

const EXCEPTIONS = new Map([
  ['θυμαρης','oxytone'],
  ['αμερης','oxytone'],
  ['απινης','adjective-gen-ous'],
  ['ακλινης','adjective-gen-ous']
]);

function keyNoAccentsLower(s){
  return stripCombiningAccents(s).toLowerCase().replace(/[^\p{L}]+/gu,'');
}

function detectEnding(word){
  const bare = stripCombiningAccents(word).toLowerCase();
  // remove final punctuation/spaces
  const w = bare.replace(/[\s··.,;:!?\-–—'’"“”()\[\]{}]+$/g,'');
  for (const r of ENDING_RULES){
    if (w.endsWith(r.ending)) return r;
  }
  return null;
}

function analyze(){
  const raw = $('inp').value.trim();
  if (!raw){
    setAnalysis('—','—','—','—','—');
    return;
  }

  const endingRule = detectEnding(raw);
  const endingText = endingRule ? endingRule.label : 'unknown';

  const k = keyNoAccentsLower(raw);
  let ruleText = '';

  if (EXCEPTIONS.has(k)){
    const t = EXCEPTIONS.get(k);
    if (t === 'oxytone') ruleText = "Marked in the passage as an oxytone adjective (exception).";
    else if (t === 'adjective-gen-ous') ruleText = "Adjective noted as having genitive in -ους (not a proper-name barytone pattern).";
  } else if (endingRule){
    ruleText = endingRule.note;
  } else {
    ruleText = "No matching ending from this passage. Try -ινης, -ονης, -υνης, -ωνης, -ξης, -πης, -αρης, -ερης, -ηρης.";
  }

  const ha = hasAnyAccent(raw);
  const oxy = accentOnLastSyllableHeuristic(raw);
  const suggestion = oxy ? moveAccentLeftOneVowel(raw) : raw;

  setAnalysis(
    endingText,
    ruleText,
    ha ? 'yes' : 'no',
    oxy ? 'yes (oxytone-ish)' : 'no (barytone-ish)',
    suggestion
  );
}

function setAnalysis(ending, rule, hasAcc, oxy, suggest){
  $('ending').textContent = ending;
  $('rule').textContent = rule;
  $('hasAccent').textContent = hasAcc;
  $('oxytone').textContent = oxy;
  $('suggest').textContent = suggest;
}

// --- Random examples + quiz ---

const EXAMPLES = [
  {w:'Αἰσχίνης', expect:'B'},
  {w:'Σμικρίνης', expect:'B'},
  {w:'Μηριόνης', expect:'B'},
  {w:'Κερύνης', expect:'B'},
  {w:'τελώνης', expect:'B'},
  {w:'Ἀράξης', expect:'B'},
  {w:'Παντικάπης', expect:'B'},
  {w:'Ὑστάσπης', expect:'B'},
  {w:'Κυαξάρης', expect:'B'},
  {w:'Δουσάρης', expect:'B'},
  {w:'Ὑπέρης', expect:'B'},
  {w:'χαλκήρης', expect:'B'},
  {w:'θυμαρής', expect:'O'},
  {w:'ἀμερής', expect:'O'},
  {w:'ἀπινής', expect:'O'},
  {w:'ἀκλινής', expect:'O'}
];

function randInt(n){ return Math.floor(Math.random()*n); }

function loadRandom(){
  const ex = EXAMPLES[randInt(EXAMPLES.length)].w;
  $('inp').value = ex;
  analyze();
}

let currentQ = null;
let score = 0;
let streak = 0;

function newRound(){
  currentQ = EXAMPLES[randInt(EXAMPLES.length)];
  $('qword').textContent = currentQ.w;
  setFeedback('Decide based on the passage’s tendencies for the ending (watch for exceptions).','warn');
}

function setFeedback(msg, kind){
  const el = $('qfb');
  el.textContent = msg;
  el.classList.remove('good','bad','warn');
  if (kind) el.classList.add(kind);
}

function answer(choice){
  if (!currentQ){
    setFeedback('Click “New round” first.','warn');
    return;
  }
  const ok = (choice === currentQ.expect);
  if (ok){
    score += 1;
    streak += 1;
    setFeedback(`Correct. ${currentQ.w} → ${choice==='B'?'barytone tendency':'exception/oxytone in the passage'}.`,'good');
  } else {
    streak = 0;
    setFeedback(`Not this time. ${currentQ.w} is treated as ${currentQ.expect==='B'?'barytone (tendency)':'an exception/oxytone'} here.`,'bad');
  }
  $('score').textContent = String(score);
  $('streak').textContent = String(streak);
}

// --- Wire up ---

$('btn').addEventListener('click', analyze);
$('inp').addEventListener('keydown', (e)=>{ if (e.key === 'Enter') analyze(); });
$('btnRandom').addEventListener('click', loadRandom);
$('btnClear').addEventListener('click', ()=>{ $('inp').value=''; analyze(); });

$('newQ').addEventListener('click', newRound);
$('ansB').addEventListener('click', ()=>answer('B'));
$('ansO').addEventListener('click', ()=>answer('O'));

// Initialize
analyze();
newRound();

